begin;
create extension if not exists pgtap with schema extensions;
select plan(46);
insert into auth.users(id,email) values ('fc100000-0000-0000-0000-000000000001','binding-admin@hero.test'),('fc100000-0000-0000-0000-000000000002','binding-inactive@hero.test'),('fc100000-0000-0000-0000-000000000003','binding-manager@hero.test');
insert into public.plants(id,code,name,display_name) values ('fc400000-0000-0000-0000-000000000001','BINDING','Binding','Binding');
insert into public.profiles(id,plant_id,role,real_name,nickname,is_active) values
('fc100000-0000-0000-0000-000000000001',null,'admin','Admin','BINDADMIN',true),('fc100000-0000-0000-0000-000000000002',null,'admin','Off','BINDOFF',false),('fc100000-0000-0000-0000-000000000003','fc400000-0000-0000-0000-000000000001','plant_manager','Manager','BINDMGR',true);
insert into public.seasons(id,season_key,title,starts_at,ends_at,status) values
