('fc200000-0000-0000-0000-000000000002','binding-test-closed','Closed',now()-interval '2 days',now()-interval '1 day','closed'),
('fc200000-0000-0000-0000-000000000003','binding-test-future','Future',now()+interval '2 days',now()+interval '3 days','scheduled');
