('fc500000-0000-0000-0000-000000000004','fc300000-0000-0000-0000-000000000002',1,'published','worker','{}'),('fc500000-0000-0000-0000-000000000005','fc300000-0000-0000-0000-000000000003',1,'published','worker','{}');
insert into public.season_scenarios(season_id,scenario_version_id,simulation_seed,is_active) values
