insert into auth.users(id,email) values ('fc100000-0000-0000-0000-000000000004','binding-player@hero.test');
insert into public.profiles(id,plant_id,role,job_role,real_name,nickname) values ('fc100000-0000-0000-0000-000000000004','fc400000-0000-0000-0000-000000000001','player','worker','Player','BINDPLAYER');
insert into public.play_sessions(id,user_id,plant_id,player_job_role,perspective_role,season_id,scenario_version_id,simulation_seed,presentation_seed,status)
values ('fc600000-0000-0000-0000-000000000001','fc100000-0000-0000-0000-000000000004','fc400000-0000-0000-0000-000000000001','worker','worker','fc200000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000001','old-seed-preserved-123','existing-presentation-seed','in_progress');
create temp table original_play as select md5(row_to_json(p)::text) as value from public.play_sessions p where id='fc600000-0000-0000-0000-000000000001';
select ok(not has_function_privilege('anon','public.admin_season_scenario_overview(uuid)','EXECUTE'),'admin_season_scenario_overview anon privilege');
select ok(not has_function_privilege('authenticated','public.admin_season_scenario_overview(uuid)','EXECUTE'),'admin_season_scenario_overview authenticated privilege');
select ok(has_function_privilege('service_role','public.admin_season_scenario_overview(uuid)','EXECUTE'),'admin_season_scenario_overview service_role privilege');
select ok(not has_function_privilege('anon','public.set_season_scenario_atomic(uuid,uuid,uuid,uuid,text)','EXECUTE'),'set_season_scenario_atomic anon privilege');
select ok(not has_function_privilege('authenticated','public.set_season_scenario_atomic(uuid,uuid,uuid,uuid,text)','EXECUTE'),'set_season_scenario_atomic authenticated privilege');
select ok(has_function_privilege('service_role','public.set_season_scenario_atomic(uuid,uuid,uuid,uuid,text)','EXECUTE'),'set_season_scenario_atomic service_role privilege');
select ok(not has_function_privilege('authenticated','public.sync_open_season_scenarios()','EXECUTE'),'legacy unaudited browser sync revoked');
set local role authenticated;
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',repeat('a',32))$$,'42501',null,'browser actor spoof denied');
reset role;
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000002','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','admin_required','inactive cannot change bindings');
select throws_ok($$select public.admin_season_scenario_overview('fc100000-0000-0000-0000-000000000002')$$,'P0001','admin_required','inactive cannot read overview');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000003','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','admin_required','manager cannot change bindings');
select throws_ok($$select public.admin_season_scenario_overview('fc100000-0000-0000-0000-000000000003')$$,'P0001','admin_required','manager cannot read overview');
select is(public.admin_season_scenario_overview('fc100000-0000-0000-0000-000000000001')->'season'->>'id','fc200000-0000-0000-0000-000000000001','overview matches current season');
select ok(exists(select 1 from jsonb_array_elements(public.admin_season_scenario_overview('fc100000-0000-0000-0000-000000000001')->'scenarios') r where r->>'id'='fc300000-0000-0000-0000-000000000001' and r->>'publishedVersionId'='fc500000-0000-0000-0000-000000000002'),'overview includes published candidate');
select ok(exists(select 1 from jsonb_array_elements(public.admin_season_scenario_overview('fc100000-0000-0000-0000-000000000001')->'scenarios') r where r->>'id'='fc300000-0000-0000-0000-000000000001' and jsonb_array_length(r->'bindings')=2),'overview includes stale and inactive binding history');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000002','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000002','fc300000-0000-0000-0000-000000000001'))$$,'P0001','season_no_longer_open','closed season cannot change');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000003','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000003','fc300000-0000-0000-0000-000000000001'))$$,'P0001','season_no_longer_open','scheduled season cannot change');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',repeat('a',32))$$,'P0001','season_binding_conflict','stale revision denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',null)$$,'P0001','season_binding_conflict','missing revision denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000006',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','scenario_version_not_published','unknown version denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000001',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','scenario_version_not_published','archived version denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000003',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','scenario_version_not_published','approval alone is not playable');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000004',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','scenario_version_not_published','cross scenario version denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000002','fc500000-0000-0000-0000-000000000004',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000002'))$$,'P0001','scenario_not_eligible','inactive catalog denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000003','fc500000-0000-0000-0000-000000000005',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000003'))$$,'P0001','scenario_not_eligible','tutorial cannot join competitive season');
create temp table original_revision as select private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001') as value;
create function pg_temp.reject_binding_audit() returns trigger language plpgsql as $$begin if new.action='season.scenario_binding_changed' then raise exception 'injected_binding_audit_failure'; end if; return new; end;$$;
create trigger reject_binding_audit before insert on public.audit_logs for each row execute function pg_temp.reject_binding_audit();
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','injected_binding_audit_failure','audit failure rolls back switching');
select ok((select is_active from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000001'),'audit failure retains old active binding');
select ok(not (select is_active from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000002'),'audit failure retains target disabled');
select is(private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'),(select value from original_revision),'audit failure preserves revision');
drop trigger reject_binding_audit on public.audit_logs;
select lives_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'connect published version');
select ok(not (select is_active from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000001'),'old binding deactivated');
select ok((select is_active from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000002'),'target active');
select is((select simulation_seed from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000002'),'existing-seed-preserved-456','existing target seed preserved');
select is((select simulation_seed from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000001'),'old-seed-preserved-123','old seed preserved');
select results_eq($$select count(*) from public.audit_logs where action='season.scenario_binding_changed' and entity_id='fc200000-0000-0000-0000-000000000001'$$,array[1::bigint],'exactly one audit committed');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',(select value from original_revision))$$,'P0001','season_binding_conflict','duplicate stale request denied');
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','binding_no_change','same connection does not duplicate audit');
select lives_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001',null,private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'disconnect');
select results_eq($$select count(*) from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and is_active$$,array[0::bigint],'disconnect disables all bindings');
select results_eq($$select count(*) from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001'$$,array[2::bigint],'disconnect preserves history rows');
select is((select md5(row_to_json(p)::text) from public.play_sessions p where id='fc600000-0000-0000-0000-000000000001'),(select value from original_play),'disconnect preserves all fields of ongoing play');
select lives_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001','fc500000-0000-0000-0000-000000000002',private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'reconnect same version');
select is((select simulation_seed from public.season_scenarios where season_id='fc200000-0000-0000-0000-000000000001' and scenario_version_id='fc500000-0000-0000-0000-000000000002'),'existing-seed-preserved-456','reconnect keeps deterministic seed');
update public.seasons set status='closed' where id='fc200000-0000-0000-0000-000000000001';
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001',null,private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','season_no_longer_open','season ending after read blocks mutation');
update public.seasons set status='open',ends_at=now()-interval '0.1 second',starts_at=now()-interval '2 seconds' where id='fc200000-0000-0000-0000-000000000001';
select throws_ok($$select public.set_season_scenario_atomic('fc100000-0000-0000-0000-000000000001','fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001',null,private.season_binding_revision('fc200000-0000-0000-0000-000000000001','fc300000-0000-0000-0000-000000000001'))$$,'P0001','season_no_longer_open','expired open season also blocked');
select is((select md5(row_to_json(p)::text) from public.play_sessions p where id='fc600000-0000-0000-0000-000000000001'),(select value from original_play),'reconnect preserves existing play version and seeds');
select * from finish();
rollback;
